def has_balanced_brackets(text: str) -> bool:
    """Check that the square brackets in :paramref:`text` are balanced."""
    depth = 0
    for character in text:
        if character == "[":
            depth += 1
        elif character == "]":
            depth -= 1
            if depth < 0:
                return False

    return depth == 0


def texts_are_unique(texts: Iterable[str]) -> bool:
    """Check that the :paramref:`texts` do not repeat."""
    text_set = set()  # type: Set[str]
    for text in texts:
        if text in text_set:
            return False

        text_set.add(text)

    return True


def items_have_unique_labels(items: Iterable[aas_types.Item]) -> bool:
    """
    Check that :py:attr:`.types.Item.label`'s of the :paramref:`items`
    do not repeat.
    """
    label_set = set()  # type: Set[str]
    for item in items:
        if item.label in label_set:
            return False

        label_set.add(item.label)

    return True


class _Transformer(
        aas_types.AbstractTransformer[
            Iterator[Error]
        ]
):
    # noinspection PyMethodMayBeStatic
    def transform_box(
            self,
            that: aas_types.Box
    ) -> Iterator[Error]:
        if not has_balanced_brackets(that.label):
            yield Error(
                'The square brackets in the label must be balanced.'
            )

    # noinspection PyMethodMayBeStatic
    def transform_bag(
            self,
            that: aas_types.Bag
    ) -> Iterator[Error]:
        if not has_balanced_brackets(that.label):
            yield Error(
                'The square brackets in the label must be balanced.'
            )

    # noinspection PyMethodMayBeStatic
    def transform_container(
            self,
            that: aas_types.Container
    ) -> Iterator[Error]:
        if not items_have_unique_labels(that.items):
            yield Error(
                'The labels must not repeat.'
            )

        if not texts_are_unique(that.names):
            yield Error(
                'The names must not repeat.'
            )

        for i, another_item in enumerate(that.items):
            for error in self.transform(another_item):
                error.path._prepend(
                    IndexSegment(
                        that.items,
                        i
                    )
                )
                error.path._prepend(
                    PropertySegment(
                        that,
                        'items'
                    )
                )
                yield error


_TRANSFORMER = _Transformer()


def verify(
        that: aas_types.Class
) -> Iterator[Error]:
    """
    Verify the constraints of :paramref:`that` recursively.

    :param that: instance whose constraints we want to verify
    :yield: constraint violations
    """
    yield from _TRANSFORMER.transform(that)


